const spareFlowChart = `
flowchart TD
    A[触发备件需求] --> B{选择需求来源}
    B -- 维修工单 --> C[按设备/零件号查询]
    B -- 定期采购计划 --> D[按机组/系统批量查询]
    B -- 库存预警 --> E[查询低库存备件]
    C --> F[AI 备件助手智能推荐]
    D --> F
    E --> F
    F --> G[匹配零件库与知识库]
    G -- 找到可用结果 --> H[展示候选备件列表]
    G -- 未找到 --> I[标记缺件/发起采购申请]
    H --> J[合规比对]
    I --> J
    J -- 存在冲突 --> K[人工确认替代件/规格]
    J -- 通过 --> L[生成采购建议或领用单]
    K --> L
    L --> M[提交审批]
    M -- 通过 --> N[执行采购/领用]
    N --> O[更新库存]
    O --> P[生成/导出台账]
    M -- 驳回 --> Q[退回补充信息]
`;
